/**
 * Bundled word lookup (IPA + meanings) used by the selection popup and inline glosses.
 * Data is generated by scripts/build-lookup-dict.ts and covers every word of every bundled
 * shadowing material, so lookups never depend on a network call that may be rate limited.
 */
import enDict from "../data/lookup/en.json";
import jaDict from "../data/lookup/ja.json";
import { annotateTerm } from "../data/word-dictionary";
import { spellAcronymIpa, tokenizeEnglish } from "./lookup-core";

export type GlossLang = "zh" | "ja";
type EnEntry = { ipa: string; zh: string; ja: string };
type JaEntry = { r: string; zh: string; en?: string; b?: string };

const EN = enDict as Record<string, EnEntry>;
const JA = jaDict as Record<string, JaEntry>;
const JA_MAX_KEY = Math.max(1, ...Object.keys(JA).map((k) => k.length));

export type EnLookup = { word: string; ipa: string | null; meaning: string | null; found: boolean };

/** UI language → explanation language for English words (English UI falls back to Chinese). */
export function glossLangFor(uiLang: string | undefined): GlossLang {
  return uiLang === "ja" ? "ja" : "zh";
}

/** UI language → explanation language for Japanese words (Chinese or English). */
export function jaGlossLangFor(uiLang: string | undefined): "zh" | "en" {
  return uiLang === "en" ? "en" : "zh";
}

function inflectionCandidates(w: string): string[] {
  const out: string[] = [];
  if (w.endsWith("'s")) out.push(w.slice(0, -2));
  if (w.endsWith("ies")) out.push(`${w.slice(0, -3)}y`);
  if (w.endsWith("es")) out.push(w.slice(0, -2));
  if (w.endsWith("s")) out.push(w.slice(0, -1));
  if (w.endsWith("ied")) out.push(`${w.slice(0, -3)}y`);
  if (w.endsWith("ed")) out.push(w.slice(0, -2), w.slice(0, -1));
  if (w.endsWith("ing")) out.push(w.slice(0, -3), `${w.slice(0, -3)}e`);
  return out.filter((x) => x.length > 1);
}

function entryFor(clean: string): EnEntry | null {
  if (EN[clean]) return EN[clean];
  for (const c of inflectionCandidates(clean)) if (EN[c]) return EN[c];
  return null;
}

/** Look up one English word (raw casing is used to detect acronyms like "API"). */
export function lookupEnglishWord(raw: string, lang: GlossLang): EnLookup {
  const token = tokenizeEnglish(raw)[0];
  if (!token) return { word: raw, ipa: null, meaning: null, found: false };
  const { clean, acronym } = token;
  const direct = entryFor(clean);
  if (direct) {
    return { word: clean, ipa: acronym ? spellAcronymIpa(clean.replace(/s$/, "")) : direct.ipa || null, meaning: direct[lang] || null, found: true };
  }
  if (clean.includes("-")) {
    const parts = clean.split("-").filter(Boolean).map((p) => lookupEnglishWord(p, lang));
    if (parts.every((p) => p.found)) {
      return {
        word: clean,
        ipa: `/${parts.map((p) => (p.ipa ?? "").replace(/^\/|\/$/g, "")).join(" ")}/`,
        meaning: parts.map((p) => p.meaning).join(" + "),
        found: true,
      };
    }
  }
  if (acronym) return { word: clean, ipa: spellAcronymIpa(clean), meaning: null, found: false };
  // Legacy built-in dictionary (Chinese only).
  const legacy = annotateTerm(clean);
  if (legacy.cn || legacy.ipa) {
    return { word: clean, ipa: legacy.ipa, meaning: lang === "zh" ? legacy.cn : null, found: Boolean(lang === "zh" ? legacy.cn : legacy.ipa) };
  }
  return { word: clean, ipa: null, meaning: null, found: false };
}

/** Short form of a meaning for inline glosses ("开始;开口" → "开始"). */
export function shortGloss(meaning: string | null | undefined): string | null {
  if (!meaning) return null;
  const text = meaning.trim();
  const inner = text.match(/[（(]([^）)]*)[）)]/)?.[1]?.trim() ?? "";
  const outer = text.replace(/（[^）]*）|\([^)]*\)/g, "").trim();
  // "API（应用程序接口）" → the parenthetical carries the meaning.
  const core = outer && !/^[A-Za-z0-9 .\-/]+$/.test(outer) ? outer : inner || outer || text;
  const first = core.split(/[;；,，、／]/)[0].trim();
  return first || core;
}

export type JaSegment = { surface: string; reading: string | null; meaning: string | null };
export type JaLookup = { text: string; reading: string | null; meaning: string | null; segments: JaSegment[]; found: boolean };

const KANA_ONLY = /^[\u3040-\u309f\u30a0-\u30ffー]+$/;

/** Greedy longest-match segmentation of Japanese text against the bundled dictionary. */
export function lookupJapanese(text: string, lang: "zh" | "en" = "zh"): JaLookup {
  const src = String(text ?? "").replace(/\s+/g, "");
  const segments: JaSegment[] = [];
  let i = 0;
  let unknown = "";
  const flushUnknown = () => {
    if (unknown) segments.push({ surface: unknown, reading: null, meaning: null });
    unknown = "";
  };
  while (i < src.length) {
    let matched: string | null = null;
    for (let len = Math.min(JA_MAX_KEY, src.length - i); len > 0; len -= 1) {
      const piece = src.slice(i, i + len);
      if (JA[piece]) { matched = piece; break; }
    }
    if (matched) {
      flushUnknown();
      const e = JA[matched];
      segments.push({ surface: matched, reading: e.r, meaning: (lang === "en" ? e.en : e.zh) || null });
      i += matched.length;
    } else {
      const ch = src[i];
      if (/[\s、。「」『』！？（）・…,.!?:：]/.test(ch)) flushUnknown();
      else unknown += ch;
      i += 1;
    }
  }
  flushUnknown();
  const contentSegs = segments.filter((s) => !/^[、。「」『』！？（）・…]+$/.test(s.surface));
  const found = contentSegs.length > 0 && contentSegs.every((s) => s.meaning || KANA_ONLY.test(s.surface));
  const reading = contentSegs.length > 0 && contentSegs.every((s) => s.reading || KANA_ONLY.test(s.surface))
    ? contentSegs.map((s) => s.reading ?? s.surface).join("")
    : null;
  const meaningful = contentSegs.filter((s) => s.meaning && !s.meaning.startsWith("（") && !s.meaning.startsWith("("));
  const meaning = contentSegs.length === 1
    ? contentSegs[0].meaning
    : meaningful.length > 0 ? meaningful.map((s) => `${s.surface}：${shortGloss(s.meaning)}`).join("　") : null;
  return { text: src, reading, meaning, segments, found };
}

export function hasEnglishEntry(word: string): boolean {
  return Boolean(entryFor(word.toLowerCase()));
}
export function hasJapaneseEntry(surface: string): boolean {
  return Boolean(JA[surface]);
}

// ── Sentence-level translations from bundled materials ──────────────────────
import { getShadowingMaterialsByLanguage } from "@toeicpass/shadowing-content";

const normSentence = (s: string) => String(s ?? "").toLowerCase().replace(/[\s"'“”‘’.,!?。、！？「」]/g, "");
let sentenceIndex: Map<string, { zh?: string; ja?: string; en?: string }> | null = null;

/** Bundled translation for a selection that is (a whole) material sentence, in the requested language. */
export function findSentenceTranslation(text: string, lang: GlossLang | "en"): string | null {
  if (!sentenceIndex) {
    sentenceIndex = new Map();
    for (const l of ["en", "ja"] as const) {
      for (const m of getShadowingMaterialsByLanguage(l)) for (const s of m.sentences) sentenceIndex.set(normSentence(s.text), s.translations);
    }
  }
  const key = normSentence(text);
  if (key.length < 4) return null;
  const hit = sentenceIndex.get(key);
  if (!hit) return null;
  return hit[lang] ?? hit.zh ?? null;
}
